import { once } from 'events';
import type { IncomingMessage, ServerResponse } from 'http';
import { GitRepo } from '../../lib/checkpoint/git.js';
import { detectRepoSlugFromGitOrigin } from '../../lib/git.js';
import { createProxyHeaders } from './ui-events-fanout.js';

const LOCAL_HOST = '127.0.0.1';
const STUDIO_CONTEXT_PATH = '/api/studio/context';

async function readBody(request: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const chunk of request) {
    if (typeof chunk === 'string') {
      chunks.push(Buffer.from(chunk));
    } else {
      chunks.push(chunk);
    }
  }
  return Buffer.concat(chunks);
}

export async function proxyApiRequest(
  request: IncomingMessage,
  response: ServerResponse,
  workerUrl: string,
  apiKey: string | null,
  reviewGithubToken: string | null,
  openrouterApiKey: string | null
): Promise<boolean> {
  const requestUrl = new URL(request.url ?? '/', `http://${LOCAL_HOST}`);
  if (requestUrl.pathname === STUDIO_CONTEXT_PATH) {
    const method = (request.method ?? 'GET').toUpperCase();
    if (method !== 'GET' && method !== 'HEAD') {
      response.statusCode = 405;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: 'Method not allowed' }));
      return true;
    }

    let repo: string | null = null;
    let branch: string | null = null;
    try {
      repo = detectRepoSlugFromGitOrigin();
    } catch {
      repo = null;
    }
    try {
      branch = new GitRepo(process.cwd()).getCurrentBranchRef();
    } catch {
      branch = null;
    }

    const payload = {
      repo,
      branch,
      detectedAt: new Date().toISOString(),
    };
    response.statusCode = 200;
    response.setHeader('Content-Type', 'application/json; charset=utf-8');
    if (method === 'HEAD') {
      response.end();
      return true;
    }
    response.end(JSON.stringify(payload));
    return true;
  }

  if (!(requestUrl.pathname === '/api' || requestUrl.pathname.startsWith('/api/'))) {
    return false;
  }

  const targetUrl = new URL(`${requestUrl.pathname}${requestUrl.search}`, workerUrl);
  const method = (request.method ?? 'GET').toUpperCase();
  const headers = createProxyHeaders(request.headers, {
    apiKey,
    reviewGithubToken,
    openrouterApiKey,
  });

  const body = method === 'GET' || method === 'HEAD' ? undefined : await readBody(request);
  const upstream = await fetch(targetUrl.toString(), {
    method,
    headers,
    body,
  });

  response.statusCode = upstream.status;
  response.statusMessage = upstream.statusText;
  upstream.headers.forEach((value, key) => {
    if (key.toLowerCase() === 'transfer-encoding') {
      return;
    }
    response.setHeader(key, value);
  });

  if (!upstream.body || method === 'HEAD') {
    response.end();
    return true;
  }

  const reader = upstream.body.getReader();
  while (true) {
    const { done, value } = await reader.read();
    if (done) {
      break;
    }
    if (!value || value.byteLength === 0) {
      continue;
    }
    if (!response.write(Buffer.from(value))) {
      await once(response, 'drain');
    }
  }
  response.end();
  return true;
}

  });
}

getRangePatch(baseRef: string, headSha: string): string {
  // Use three-dot range for PR-style diffs: merge-base(baseRef, headSha)..headSha.
  // This isolates branch-introduced changes relative to the base branch.
  return this.run(['diff', '--no-ext-diff', '--unified=3', `${baseRef}...${headSha}`], {
    maxBuffer: LARGE_GIT_OUTPUT_MAX_BUFFER_BYTES,
  });
}

listCommits(ref: string): CommitHistoryEntry[] {
  const output = this.run(['log', '--format=%H%x1f%B%x1e', ref]);
  return parseGitLogOutput(output);
}

getCurrentBranchRef(): string | null {
  try {
    const output = this.run(['symbolic-ref', '--quiet', '--short', 'HEAD']).trim();
    return output || null;
  } catch {
    return null;
  }
}

listTreePaths(sha: string): string[] {
  const output = this.run(['ls-tree', '-r', '--name-only', sha]);
  return parseGitLsTreeNameOnlyOutput(output);
}

readFileAtCommit(sha: string, path: string): string {
  return this.run(['show', `${sha}:${path}`]);
}

listTreeFileEntriesForProjectDetection(sha: string): TreeFileEntry[] {
  const paths = this.listTreePaths(sha);
  const entries: TreeFileEntry[] = [];

  for (const path of paths) {
    if (path.endsWith('/package.json') || path === 'package.json') {
      entries.push({
        path,
        content: this.readFileAtCommit(sha, path),
      });
    } else {
      entries.push({ path });
    }
  }

  return entries;
}

ensureNoSubmodules(sha: string): void {
  const output = this.run(['ls-tree', '-r', sha]);
  if (treeOutputHasSubmodule(output)) {
    throw new Error(
      'Checkpoint deploy does not support git submodules in MVP. Remove submodules or choose a different commit.'
    );
  }
}

import * as p from '@clack/prompts';
import { spawn } from 'child_process';
import {
  resolveMonorepoDistDir,
  resolveMonorepoReportUiDir,
  resolvePackagedDistDir,
} from './ui-static.js';
import { startDevServerSession } from './ui-dev-server.js';
import { startStaticServerSession } from './ui-static-server.js';

const LOCAL_HOST = '127.0.0.1';

export interface UiServerSession {
  appUrl: string;
  uiMode: 'static' | 'dev';
  close: () => Promise<void>;
  waitForExit: () => Promise<void>;
}

export function openBrowser(url: string): void {
  const platform = process.platform;
  const command = platform === 'win32' ? 'cmd' : platform === 'darwin' ? 'open' : 'xdg-open';
  const args = platform === 'win32' ? ['/c', 'start', '', url] : [url];
  const child = spawn(command, args, {
    detached: true,
    stdio: 'ignore',
  });
  child.unref();
}

export async function startReportUiSession(options: {
  routePath: string;
  port: number;
  workerUrl: string;
  apiKey: string | null;
  reviewGithubToken: string | null;
  openrouterApiKey: string | null;
  preferDevServer?: boolean;
}): Promise<UiServerSession> {
  if (options.preferDevServer) {
    const reportUiDir = resolveMonorepoReportUiDir();
    if (!reportUiDir) {
      throw new Error('Unable to locate monorepo report-ui package for --dev-ui mode.');
    }
    return startDevServerSession({
      routePath: options.routePath,
      reportUiDir,
      workerUrl: options.workerUrl,
      port: options.port,
    });
  }

  const bundledDistDir = resolvePackagedDistDir();
  const monorepoDistDir = resolveMonorepoDistDir();
  const distDir = bundledDistDir ?? monorepoDistDir;

  if (distDir) {
    p.log.message(
      `Serving report UI assets from ${distDir} on ${LOCAL_HOST}:${options.port} with API proxy target ${options.workerUrl}`
    );
    return startStaticServerSession({
      routePath: options.routePath,
      distDir,
      workerUrl: options.workerUrl,
      apiKey: options.apiKey,
      reviewGithubToken: options.reviewGithubToken,
      openrouterApiKey: options.openrouterApiKey,
      port: options.port,
    });
  }

  const reportUiDir = resolveMonorepoReportUiDir();
  if (!reportUiDir) {
    throw new Error('Unable to locate bundled report UI assets or monorepo report-ui package. Reinstall or rebuild the CLI package.');
  }

  return startDevServerSession({
    routePath: options.routePath,
    reportUiDir,
    workerUrl: options.workerUrl,
    port: options.port,
  });
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import { execFileSync } from 'child_process';

const REPORT_UI_MARKER = 'nimbus-report-ui';
const REPORT_UI_HEALTH_PATH = '/__nimbus/report-ui-health';
const STUDIO_CONTEXT_PATH = '/api/studio/context';
const REPO_SLUG_PATTERN = /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/;

function parseRepoSlug(remoteUrl: string): string | null {
  const trimmed = remoteUrl.trim();
  if (!trimmed) {
    return null;
  }

  if (trimmed.startsWith('git@')) {
    const idx = trimmed.indexOf(':');
    if (idx < 0) {
      return null;
    }
    const path = trimmed.slice(idx + 1).replace(/\.git$/i, '');
    return REPO_SLUG_PATTERN.test(path) ? path : null;
  }

  try {
    const parsed = new URL(trimmed);
    const path = parsed.pathname.replace(/^\//, '').replace(/\.git$/i, '');
    return REPO_SLUG_PATTERN.test(path) ? path : null;
  } catch {
    return null;
  }
}

function readGitBranch(): string | null {
  try {
    const branch = execFileSync('git', ['symbolic-ref', '--quiet', '--short', 'HEAD'], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    })
      .toString()
      .trim();
    return branch || null;
  } catch {
    return null;
  }
}

function readGitRepoSlug(): string | null {
  try {
    const origin = execFileSync('git', ['remote', 'get-url', 'origin'], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    })
      .toString()
      .trim();
    return parseRepoSlug(origin);
  } catch {
    return null;
  }
}

function reportUiHealthPlugin() {
  return {
    name: 'nimbus-report-ui-health',
    configureServer(server: {
      middlewares: {
        use: (
          handler: (
            req: { url?: string; method?: string },
            res: {
              statusCode: number;
              setHeader: (name: string, value: string) => void;
              end: (body?: string) => void;
            },
            next: () => void
          ) => void
        ) => void;
      };
    }) {
      server.middlewares.use((req, res, next) => {
        const requestUrl = new URL(req.url ?? '/', 'http://127.0.0.1');
        if (requestUrl.pathname !== REPORT_UI_HEALTH_PATH) {
          next();
          return;
        }

        const method = (req.method ?? 'GET').toUpperCase();
        if (method !== 'GET' && method !== 'HEAD') {
          res.statusCode = 405;
          res.setHeader('Content-Type', 'text/plain; charset=utf-8');
          res.end('Method not allowed');
          return;
        }

        const body = JSON.stringify({
          service: REPORT_UI_MARKER,
          host: '127.0.0.1',
          workerUrl: process.env.NIMBUS_REPORT_UI_HEALTH_WORKER_URL ?? process.env.NIMBUS_API_PROXY_TARGET ?? null,
          authFingerprint: process.env.NIMBUS_REPORT_UI_HEALTH_AUTH_FINGERPRINT ?? null,
        });

        res.statusCode = 200;
        res.setHeader('Cache-Control', 'no-store');
        res.setHeader('Content-Type', 'application/json; charset=utf-8');
        res.setHeader('Content-Length', String(Buffer.byteLength(body, 'utf8')));
        if (method === 'HEAD') {
          res.end();
          return;
        }
        res.end(body);
      });
    },
  };
}

function studioContextPlugin() {
  return {
    name: 'nimbus-studio-context',
    configureServer(server: {
      middlewares: {
        use: (
          handler: (
            req: { url?: string; method?: string },
            res: {
              statusCode: number;
              setHeader: (name: string, value: string) => void;
              end: (body?: string) => void;
            },
            next: () => void
