export interface ResolveReviewContextResult {
  workspaceId: string;
  deploymentId: string;
  resolvedProvenance: ReviewCreateProvenance;
}

export interface ReviewContextFlowOverrides {
  createWorkspace?: typeof createWorkspaceForCommitFlow;
  resolveWorkspaceSource?: typeof resolveWorkspaceSourceForCommitFlow;
  deployWorkspace?: typeof deployWorkspaceForCommitFlow;
  resolveLocalCochange?: typeof resolveLocalCochangeForCommitFlow;
}

function toErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function buildReviewFlowStageError(stage: string, error: unknown): Error {
  return new Error(`Review flow failed at ${stage}: ${toErrorMessage(error)}`);
}

let createWorkspaceForCommitFlow: (source: {
  commitSha: string;
  checkpointId: string | null;
  sourceRef: string | null;
  projectRoot: string;
}) => Promise<{ workspace: WorkspaceResponse }> = createWorkspaceFromResolvedSource;
let resolveWorkspaceSourceForCommitFlow: typeof resolveWorkspaceSource = resolveWorkspaceSource;
let deployWorkspaceForCommitFlow: (
  workspaceId: string,
  options: Parameters<typeof workspaceDeployCommand>[1]
) => Promise<WorkspaceDeploymentResponse | null> = workspaceDeployCommand;
let resolveLocalCochangeForCommitFlow: typeof resolveCochangeFromLocalGit = resolveCochangeFromLocalGit;

export function setReviewCommitResolverForTests(
  resolver: ((commitish: string, options?: { baseRef?: string }) => CommitResolution) | null
): void {
  setReviewPreflightCommitResolverForTests(resolver);
}

export function setReviewContextFlowForTests(overrides: ReviewContextFlowOverrides | null): void {
  createWorkspaceForCommitFlow = overrides?.createWorkspace ?? createWorkspaceFromResolvedSource;
  resolveWorkspaceSourceForCommitFlow = overrides?.resolveWorkspaceSource ?? resolveWorkspaceSource;
  deployWorkspaceForCommitFlow = overrides?.deployWorkspace ?? workspaceDeployCommand;
  resolveLocalCochangeForCommitFlow = overrides?.resolveLocalCochange ?? resolveCochangeFromLocalGit;
}

/**
 * Orchestrates review context setup from a commit by validating Entire metadata,
 * creating a workspace, deploying it, then assembling provenance for review creation.
 */
export async function resolveReviewContext(
  options?: ResolveReviewContextOptions
): Promise<ResolveReviewContextResult> {
  const commitish = options?.commitish?.trim() || 'HEAD';
  const projectRoot = options?.projectRoot?.trim() || '.';
  const spinner: SpinnerLike =
    process.stdout.isTTY && process.stderr.isTTY
      ? p.spinner()
      : {
          start: () => undefined,
          message: () => undefined,
          stop: () => undefined,
        };

  let commitSha = '';
  let checkpointId = '';
  let commitDiffPatch = '';
  let workspaceId = '';
  let deploymentId = '';
  let commitDiffPatchSha256 = '';
  let commitDiffPatchTruncated = false;
  let commitDiffPatchOriginalChars = 0;
  let entireContextResolution: ReviewEntireContextResolution | null = null;
  let localCochange:
    | {
        source: 'local_git';
        checkpointsRef: string;
        lookbackSessions: number;
        topN: number;
        sessionsScanned: number;
        relatedByChangedPath: Record<string, Array<{ path: string; frequency: number; sessionIds: string[] }>>;
      }
    | null = null;
  let changedPaths: string[] = [];
  let gitProvenance: { repo: string; branch: string } = { repo: '', branch: '' };

  spinner.start('Resolving checkpoint...');
  try {
    gitProvenance = resolveReviewGitProvenance();
    const resolvedCommit = validateReviewCommitCheckpoint(commitish, process.cwd(), {
      baseRef: options?.baseRef,
    });
    commitSha = resolvedCommit.commitSha;
    checkpointId = resolvedCommit.checkpointId;
    changedPaths = parseChangedPathsFromDiff(resolvedCommit.commitDiffPatch);
    const normalizedPatch = normalizeCommitDiffPatch(resolvedCommit.commitDiffPatch);
    commitDiffPatch = normalizedPatch.patch;
    commitDiffPatchSha256 = normalizedPatch.sha256;
    commitDiffPatchTruncated = normalizedPatch.truncated;
    commitDiffPatchOriginalChars = normalizedPatch.originalChars;
    spinner.stop(`Resolved checkpoint ${checkpointId} from ${commitSha.slice(0, 12)}`);
  } catch (error) {
    spinner.stop('Checkpoint resolution failed');
    throw buildReviewFlowStageError('checkpoint resolution', error);
  }

  spinner.start('Validating Entire session metadata...');
  try {
    entireContextResolution = await validateReviewEntireIntentContext(
      {
        commitSha,
        checkpointId,
      },
      {
        summarizeSession: 'auto',
        allowBranchFallback: true,
      },
      process.cwd()
    );

    spinner.stop(
      entireContextResolution.contextResolution === 'branch_fallback'
        ? `Entire session metadata resolved via branch fallback (${entireContextResolution.resolvedCheckpointId})`
        : 'Entire session metadata is readable'
    );
    if (entireContextResolution.contextResolution === 'branch_fallback') {
      p.log.warning(
        `Using fallback Entire context from commit ${entireContextResolution.resolvedCommitSha.slice(0, 7)} ('${entireContextResolution.resolvedCommitSubject}') ${entireContextResolution.commitsAgo} commits ago.`
      );
    }
  } catch (error) {
    spinner.stop('Entire session metadata validation failed');
    throw buildReviewFlowStageError('checkpoint resolution', error);
  }

  spinner.start('Resolving local co-change context...');
  try {
    localCochange = resolveLocalCochangeForCommitFlow(changedPaths, process.cwd(), {
      lookbackSessions: COCHANGE_LOOKBACK_SESSIONS,
      topN: COCHANGE_TOP_N,
    });
    if (localCochange) {
      spinner.stop(
        `Resolved local co-change context from ${localCochange.checkpointsRef} (${localCochange.sessionsScanned} sessions scanned)`
      );
    } else {
      spinner.stop('Local co-change context unavailable (worker will use GitHub fallback)');
    }
  } catch (error) {
    localCochange = null;
    const message = toErrorMessage(error);
    if (!isExpectedLocalCochangeResolutionError(message)) {
      p.log.warning(`Local co-change resolution error: ${message}`);
    }
    spinner.stop('Local co-change context unavailable (worker will use GitHub fallback)');
  }

  spinner.start('Checking co-change token readiness...');
  try {
    if (localCochange) {
      spinner.stop('Co-change token check skipped (using local co-change context)');
    } else {
      await validateReviewCochangeTokenReadiness();
      spinner.stop('Co-change token readiness confirmed');
    }
  } catch (error) {
    spinner.stop('Co-change token readiness check failed');
    throw buildReviewFlowStageError('checkpoint resolution', error);
  }

  spinner.start('Creating workspace...');
  try {
    const sourceResolved = resolveWorkspaceSourceForCommitFlow(commitSha, { projectRoot });
    const source = {
      ...sourceResolved,
      checkpointId,
    };
    const created = await createWorkspaceForCommitFlow(source);
    workspaceId = created.workspace.id;
    spinner.stop(`Workspace created: ${workspaceId}`);
  } catch (error) {
    spinner.stop('Workspace creation failed');
    throw buildReviewFlowStageError('workspace creation', error);
  }

  spinner.start('Deploying workspace...');
  try {
    const deploymentIdempotencyKey = options?.idempotencyKey?.trim()
      ? deriveIdempotencyKey(options.idempotencyKey, 'deploy')
      : buildWorkspaceIdempotencyKey(commitSha);
    const deployment = await deployWorkspaceForCommitFlow(workspaceId, {
      idempotencyKey: deploymentIdempotencyKey,
      runTestsIfPresent: false,
      runBuildIfPresent: false,
      autoFix: false,
      pollIntervalMs: options?.pollIntervalMs,
      reporter: {
        message: (text) => spinner.message(text),
        success: (text) => spinner.message(text),
        warning: (text) => spinner.message(text),
        error: (text) => spinner.message(text),
      },
      entireIntentContextOverride: entireContextResolution ?? undefined,
    });
    if (!deployment) {
      throw new Error('Workspace deploy returned no deployment result.');
    }
    deploymentId = deployment.id;
    spinner.stop(`Deployment succeeded: ${deploymentId}`);
  } catch (error) {
    spinner.stop('Workspace deploy failed');
    throw buildReviewFlowStageError('workspace deploy', error);
  }

    }

    const outputReviewIdRaw = options?.outputReviewIdPath;
    const outputReviewIdPath = outputReviewIdRaw?.trim();
    if (outputReviewIdRaw !== undefined && !outputReviewIdPath) {
      p.log.warning('Ignoring --output-review-id because the provided path is empty.');
    }
    if (outputReviewIdPath) {
      try {
        const repoRoot = new GitRepo(process.cwd()).getRepoRoot();
        const workspaceDir = typeof process.env.GITHUB_WORKSPACE === 'string' && process.env.GITHUB_WORKSPACE.trim()
          ? process.env.GITHUB_WORKSPACE.trim()
          : null;
        let baseDir = repoRoot;
        if (workspaceDir) {
          const resolvedWorkspaceDir = resolve(workspaceDir);
          const resolvedRepoRoot = resolve(repoRoot);
          if (
            resolvedWorkspaceDir === resolvedRepoRoot ||
            resolvedWorkspaceDir.startsWith(`${resolvedRepoRoot}/`)
          ) {
            baseDir = resolvedWorkspaceDir;
          } else {
            p.log.warning(
              `Ignoring GITHUB_WORKSPACE=${workspaceDir} because it is outside the repository root; resolving --output-review-id from repo root instead.`
            );
          }
        }
        const absolutePath = isAbsolute(outputReviewIdPath)
          ? outputReviewIdPath
          : resolve(baseDir, outputReviewIdPath);
        await mkdir(dirname(absolutePath), { recursive: true });
        await writeFile(absolutePath, `${reviewId}\n`, 'utf8');
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        throw new Error(
          `Could not write review ID file at ${outputReviewIdPath}: ${message}. Review creation failed because downstream automation expects this file.`
        );
      }
    }
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    spinner.stop('Review creation failed');
    throw new Error(`Review flow failed at review creation: ${message}`);
  }

  if (options?.openStudio) {
    await startReviewStudioCommand({
      port: options.openStudioPort,
      routePath:
        policyMode === 'review'
          ? `/policy/${encodeURIComponent(reviewId)}`
          : `/reports/${encodeURIComponent(reviewId)}`,
      detach: true,
    });
  }

  if (policyMode === 'review') {
    p.log.message('Policy review is required before execution. Open the policy page and approve to start the run.');
    console.log(`Report URL: ${reviewResultUrl}`);
    return;
  }

  p.log.info(`Streaming review events for ${reviewId}`);
  let terminalStatus: string | null = null;
  let lastFailureEvent: Record<string, unknown> | null = null;
  let streamErrorMessage: string | null = null;
  try {
    await streamReviewEventsForCommitFlow(workerUrl, reviewId, async (event) => {
      const line = formatEvent(event);
      if (line) {
        console.log(line);
      }
      if (
        event.data.type === 'review_context_cochange_failed' ||
        event.data.type === 'review_context_assembly_failed' ||
        event.data.type === 'review_failed'
      ) {
        lastFailureEvent = event.data;
      }
      if (event.data.type === 'terminal' && typeof event.data.status === 'string') {
        terminalStatus = event.data.status;
      }
    });
  } catch (error) {
    streamErrorMessage = error instanceof Error ? error.message : String(error);
    p.log.warning(`Event stream interrupted before terminal status: ${streamErrorMessage}`);
  }

  let final = await getReviewForCommitFlow(workerUrl, reviewId);
  if (!terminalStatus && (final.review.status === 'queued' || final.review.status === 'running')) {
    p.log.warning('Review still in progress after event stream ended; falling back to status polling.');
    final = await pollReviewUntilTerminalStatus(workerUrl, reviewId, {
      intervalMs: options?.pollIntervalMs,
    });
  }

  const status = typeof terminalStatus === 'string' ? terminalStatus : final.review.status;
  if (status !== 'succeeded') {
    if (streamErrorMessage) {
      p.log.warning(`Latest stream interruption detail: ${streamErrorMessage}`);
    }
    throw new Error(formatReviewExecutionFailure(status, final.review, lastFailureEvent));
  }

  console.log(`Report URL: ${reviewResultUrl}`);
}

import * as p from '@clack/prompts';
import { approveReviewPolicy, createReview, deriveReviewPolicy } from '../../clients/worker/reviews.js';
import { getWorkerUrl } from '../../clients/worker/shared.js';
import { validateReviewCochangeTokenReadiness } from '../../commands/review/preflight.js';
import { startReviewStudioCommand } from './open.js';
import { buildIdempotencyKey, resolveReviewGitProvenance } from './create-shared.js';

export async function createReviewCommand(
  workspaceId: string,
  deploymentId: string,
  options?: {
    idempotencyKey?: string;
    policyMode?: 'none' | 'auto' | 'review';
    reviewBasis?: 'checkpoint' | 'environment';
    openStudio?: boolean;
    openStudioPort?: number;
    severityThreshold?: 'low' | 'medium' | 'high' | 'critical';
    maxFindings?: number;
    model?: string;
    intentSummaryModel?: string;
    includeProvenance?: boolean;
    includeValidationEvidence?: boolean;
  }
): Promise<void> {
  const workerUrl = getWorkerUrl();
  if (!workerUrl) {
    throw new Error('NIMBUS_WORKER_URL environment variable is required');
  }

  await validateReviewCochangeTokenReadiness();
  const policyMode = options?.policyMode ?? 'none';
  const reviewBasis = options?.reviewBasis ?? 'checkpoint';

  const gitProvenance = resolveReviewGitProvenance();

  const provenance = {
    repo: gitProvenance.repo,
    branch: gitProvenance.branch,
    ...(options?.intentSummaryModel?.trim() ? { intentSummaryModel: options.intentSummaryModel.trim() } : {}),
  };

  let reviewId = '';
  let status = '';
  let resultUrl = '';
  let eventsUrl = '';
  if (policyMode === 'none') {
    const response = await createReview(workerUrl, options?.idempotencyKey?.trim() || buildIdempotencyKey(workspaceId, deploymentId), {
      target: {
        type: 'workspace_deployment',
        workspaceId,
        deploymentId,
      },
      mode: 'report_only',
      policyMode,
      reviewBasis,
      policy: {
        severityThreshold: options?.severityThreshold ?? 'low',
        maxFindings: options?.maxFindings,
        includeProvenance: options?.includeProvenance ?? true,
        includeValidationEvidence: options?.includeValidationEvidence ?? true,
      },
      model: options?.model,
      provenance,
    });
    reviewId = response.reviewId;
    status = response.status;
    resultUrl = response.resultUrl;
    eventsUrl = response.eventsUrl;
  } else {
    const derived = await deriveReviewPolicy(workerUrl, {
      workspaceId,
      deploymentId,
      policyMode,
      reviewBasis,
      provenance,
    });
    reviewId = derived.reviewId;
    if (policyMode === 'auto') {
      await approveReviewPolicy(workerUrl, reviewId, {
        approvedPolicy: derived.derivedPolicy,
      });
      status = 'policy_approved';
    } else {
      status = derived.status;
    }
    resultUrl = `${workerUrl}/api/reviews/${encodeURIComponent(reviewId)}`;
    eventsUrl = `${workerUrl}/api/reviews/${encodeURIComponent(reviewId)}/events`;
  }

  p.log.success(`Review queued: ${reviewId}`);
  p.log.message(`Policy mode: ${policyMode}`);
  p.log.message(`Review basis: ${reviewBasis}`);
  p.log.message(`Status: ${status}`);
  p.log.message(`Result URL: ${resultUrl}`);
  p.log.message(`Events URL: ${eventsUrl}`);

  if (options?.openStudio) {
    await startReviewStudioCommand({
      port: options.openStudioPort,
      routePath: policyMode === 'review' ? `/policy/${encodeURIComponent(reviewId)}` : `/reports/${encodeURIComponent(reviewId)}`,
      detach: true,
    });
  }
}

  }

  if (reviewAction === 'export') {
    const reviewId = positional[1];
    const formatFlag = flags.format;
    const outFlag = flags.out;
    const format = typeof formatFlag === 'string' ? formatFlag : 'markdown';
    const outputPath = typeof outFlag === 'string' ? outFlag : undefined;
    if (!reviewId || !outputPath) {
      exitWithUsage('Usage: nimbus review export <review-id> --format <markdown|json> --out <path>');
    }
    if (format !== 'markdown' && format !== 'json') {
      exitWithUsage('Invalid --format value. Use markdown or json.');
    }

    await exportReviewCommand(reviewId, format, outputPath);
    return;
  }

  if (reviewAction === 'open') {
    const unexpectedPositional = positional[1];
    if (typeof unexpectedPositional === 'string' && unexpectedPositional.trim()) {
      exitWithUsage('Usage: nimbus review open [--commit <commit-ish>] [--port <n>] [--base <ref>] [--project-root <path>]');
    }

    await openReviewFromCommitCommand({
      port: parsePositiveIntegerFlag(flags.port),
      commitish: typeof flags.commit === 'string' ? flags.commit : 'HEAD',
      baseRef: typeof flags.base === 'string' && flags.base.trim() ? flags.base.trim() : undefined,
      projectRoot: typeof flags['project-root'] === 'string' && flags['project-root'].trim() ? flags['project-root'].trim() : undefined,
      idempotencyKey:
        typeof flags['idempotency-key'] === 'string' && flags['idempotency-key'].trim()
          ? flags['idempotency-key'].trim()
          : undefined,
      pollIntervalMs: parsePositiveIntegerFlag(flags['poll-interval-ms']),
    });
    return;
  }

  if (reviewAction === 'studio' || reviewAction === 'start') {
    const unexpectedPositional = positional[1];
    if (typeof unexpectedPositional === 'string' && unexpectedPositional.trim()) {
      exitWithUsage('Usage: nimbus review studio [--port <n>] [--detach]');
    }
    if (flags.serve && flags.status) {
      exitWithUsage('Usage error: --serve and --status cannot be used together.');
    }
    if (flags.serve && flags.stop) {
      exitWithUsage('Usage error: --serve and --stop cannot be used together.');
    }
    if (flags.status && flags.stop) {
      exitWithUsage('Usage error: --status and --stop cannot be used together.');
    }
    if (flags['dev-ui'] && flags.status) {
      exitWithUsage('Usage error: --dev-ui and --status cannot be used together.');
    }
    if (flags['dev-ui'] && flags.stop) {
      exitWithUsage('Usage error: --dev-ui and --stop cannot be used together.');
    }
    if (flags.detach && flags.serve) {
      exitWithUsage('Usage error: --detach and --serve cannot be used together.');
    }
    if (flags.detach && flags.status) {
      exitWithUsage('Usage error: --detach and --status cannot be used together.');
    }
    if (flags.detach && flags.stop) {
      exitWithUsage('Usage error: --detach and --stop cannot be used together.');
    }

    await startReviewStudioCommand({
      port: parsePositiveIntegerFlag(flags.port),
      serve: Boolean(flags.serve),
      status: Boolean(flags.status),
      stop: Boolean(flags.stop),
      devUi: Boolean(flags['dev-ui']),
      detach: Boolean(flags.detach),
    });
    return;
  }

  exitWithUsage('Unknown review command. Use: create, preflight, policy, show, events, studio, open, export');
}

import { approveReviewPolicy, deriveReviewPolicy } from '../../clients/worker/reviews.js';
import { getWorkerUrl } from '../../clients/worker/shared.js';
import { validateReviewCommitCheckpoint, validateReviewEntireIntentContext } from '../../commands/review/preflight.js';
import { resolveReviewContext } from './context.js';
import { resolveReviewGitProvenance } from './create-shared.js';
import { readStudioPreferences, updateStudioPolicyMode } from './session.js';

export type StudioReviewPolicyMode = 'auto' | 'review';

export interface StudioNewReviewPreflightResult {
  repo: string | null;
  branch: string | null;
  policyMode: StudioReviewPolicyMode;
  checkpointId: string | null;
  commitSha: string | null;
  ready: boolean;
  checks: Array<{
    code: 'checkpoint' | 'entire_context';
    label: string;
    ok: boolean;
    detail: string;
  }>;
  error?: {
    code: 'checkpoint_unavailable' | 'entire_context_unavailable' | 'unknown';
    message: string;
  };
}

export interface StudioNewReviewStartResult {
  reviewId: string;
  routePath: string;
  policyMode: StudioReviewPolicyMode;
  status: 'policy_ready' | 'queued';
}

function preflightErrorCode(message: string): NonNullable<StudioNewReviewPreflightResult['error']>['code'] {
  const lower = message.toLowerCase();
  if (lower.includes('entire-checkpoint trailer') || lower.includes('no entire session history')) {
    return 'checkpoint_unavailable';
  }
  if (lower.includes('entire session') || lower.includes('checkpoint context')) {
    return 'entire_context_unavailable';
  }
  return 'unknown';
}

function normalizeStudioPolicyMode(value: string | null | undefined): StudioReviewPolicyMode {
  return value === 'review' ? 'review' : 'auto';
}

export async function resolveStudioNewReviewPreflight(): Promise<StudioNewReviewPreflightResult> {
  const preferences = await readStudioPreferences();
  const policyMode = normalizeStudioPolicyMode(preferences.policyMode);
  let repo: string | null = null;
  let branch: string | null = null;
  try {
    const gitProvenance = resolveReviewGitProvenance();
    repo = gitProvenance.repo;
    branch = gitProvenance.branch;
  } catch {
    repo = null;
    branch = null;
  }

  let commitSha: string | null = null;
  let checkpointId: string | null = null;
  try {
    const checkpoint = validateReviewCommitCheckpoint('HEAD', process.cwd());
    commitSha = checkpoint.commitSha;
    checkpointId = checkpoint.checkpointId;
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      repo,
      branch,
      policyMode,
      checkpointId: null,
      commitSha: null,
      ready: false,
      checks: [
        {
          code: 'checkpoint',
          label: 'Checkpoint target',
          ok: false,
          detail: message,
        },
        {
          code: 'entire_context',
          label: 'Entire context',
          ok: false,
          detail: 'Blocked until checkpoint target is available.',
        },
      ],
      error: {
        code: preflightErrorCode(message),
        message,
      },
    };
  }

  try {
    const context = await validateReviewEntireIntentContext(
      {
        commitSha,
        checkpointId,
      },
      {
        summarizeSession: 'auto',
        allowBranchFallback: true,
      },
      process.cwd()
    );
    const contextDetail =
      context.contextResolution === 'branch_fallback'
        ? `Using branch fallback checkpoint ${context.resolvedCheckpointId} from ${context.commitsAgo} commit(s) ago.`
        : 'Readable Entire checkpoint context found for current commit.';
    return {
      repo,
      branch,
      policyMode,
      checkpointId,
      commitSha,
      ready: true,
      checks: [
        {
          code: 'checkpoint',
          label: 'Checkpoint target',
          ok: true,
          detail: `Resolved checkpoint ${checkpointId} from ${commitSha.slice(0, 12)}.`,
        },
        {
          code: 'entire_context',
          label: 'Entire context',
          ok: true,
          detail: contextDetail,
        },
      ],
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      repo,
      branch,
      policyMode,
      checkpointId,
      commitSha,
      ready: false,
      checks: [
        {
          code: 'checkpoint',
          label: 'Checkpoint target',
          ok: true,
          detail: `Resolved checkpoint ${checkpointId} from ${commitSha.slice(0, 12)}.`,
        },
        {
          code: 'entire_context',
          label: 'Entire context',
          ok: false,
          detail: message,
        },
      ],
      error: {
        code: preflightErrorCode(message),
        message,
      },
    };
  }
}

export async function startStudioNewReview(options: {
  policyMode: StudioReviewPolicyMode;
}): Promise<StudioNewReviewStartResult> {
  const policyMode = normalizeStudioPolicyMode(options.policyMode);
  const workerUrl = getWorkerUrl();
  if (!workerUrl) {
    throw new Error('NIMBUS_WORKER_URL environment variable is required');
  }

  await updateStudioPolicyMode(policyMode);
  const resolved = await resolveReviewContext({
    commitish: 'HEAD',
    projectRoot: '.',
  });

  if (policyMode === 'review') {
    const derived = await deriveReviewPolicy(workerUrl, {
      workspaceId: resolved.workspaceId,
      deploymentId: resolved.deploymentId,
      policyMode: 'review',
      reviewBasis: 'checkpoint',
      provenance: resolved.resolvedProvenance,
    });

    return {
      reviewId: derived.reviewId,
      routePath: `/policy/${encodeURIComponent(derived.reviewId)}`,
      policyMode,
      status: 'policy_ready',
    };
  }

  const derived = await deriveReviewPolicy(workerUrl, {
    workspaceId: resolved.workspaceId,
    deploymentId: resolved.deploymentId,
    policyMode: 'auto',
    reviewBasis: 'checkpoint',
    provenance: resolved.resolvedProvenance,
  });
  await approveReviewPolicy(workerUrl, derived.reviewId, {
    approvedPolicy: derived.derivedPolicy,
  });

  return {
    reviewId: derived.reviewId,
    routePath: `/reports/${encodeURIComponent(derived.reviewId)}`,
    policyMode,
    status: 'queued',
  };
}

import { once } from 'events';
import type { IncomingMessage, ServerResponse } from 'http';
import { GitRepo } from '../../lib/checkpoint/git.js';
import { detectRepoSlugFromGitOrigin } from '../../lib/git.js';
import { startStudioNewReview } from './studio-create.js';
import { getStudioNewReviewPreflightCached } from './studio-preflight-cache.js';
import { createProxyHeaders } from './ui-events-fanout.js';

const LOCAL_HOST = '127.0.0.1';
const STUDIO_CONTEXT_PATH = '/api/studio/context';
const STUDIO_NEW_REVIEW_PREFLIGHT_PATH = '/api/studio/new-review/preflight';
const STUDIO_NEW_REVIEW_START_PATH = '/api/studio/new-review/start';

async function readBody(request: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const chunk of request) {
    if (typeof chunk === 'string') {
      chunks.push(Buffer.from(chunk));
    } else {
      chunks.push(chunk);
    }
  }
  return Buffer.concat(chunks);
}

export async function proxyApiRequest(
  request: IncomingMessage,
  response: ServerResponse,
  workerUrl: string,
  apiKey: string | null,
  reviewGithubToken: string | null,
  openrouterApiKey: string | null
): Promise<boolean> {
  const requestUrl = new URL(request.url ?? '/', `http://${LOCAL_HOST}`);
  if (requestUrl.pathname === STUDIO_CONTEXT_PATH) {
    const method = (request.method ?? 'GET').toUpperCase();
    if (method !== 'GET' && method !== 'HEAD') {
      response.statusCode = 405;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: 'Method not allowed' }));
      return true;
    }

    let repo: string | null = null;
    let branch: string | null = null;
    try {
      repo = detectRepoSlugFromGitOrigin();
    } catch {
      repo = null;
    }
    try {
      branch = new GitRepo(process.cwd()).getCurrentBranchRef();
    } catch {
      branch = null;
    }

    const payload = {
      repo,
      branch,
      detectedAt: new Date().toISOString(),
    };
    response.statusCode = 200;
    response.setHeader('Content-Type', 'application/json; charset=utf-8');
    if (method === 'HEAD') {
      response.end();
      return true;
    }
    response.end(JSON.stringify(payload));
    return true;
  }

  if (requestUrl.pathname === STUDIO_NEW_REVIEW_PREFLIGHT_PATH) {
    const method = (request.method ?? 'GET').toUpperCase();
    if (method !== 'GET' && method !== 'HEAD') {
      response.statusCode = 405;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: 'Method not allowed' }));
      return true;
    }
    try {
      const payload = await getStudioNewReviewPreflightCached();
      response.statusCode = 200;
      response.setHeader('Cache-Control', 'no-store');
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      if (method === 'HEAD') {
        response.end();
        return true;
      }
      response.end(JSON.stringify(payload));
      return true;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      response.statusCode = 500;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: `Failed to load Studio preflight: ${message}` }));
      return true;
    }
  }

  if (requestUrl.pathname === STUDIO_NEW_REVIEW_START_PATH) {
    const method = (request.method ?? 'POST').toUpperCase();
    if (method !== 'POST') {
      response.statusCode = 405;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: 'Method not allowed' }));
      return true;
    }
    try {
      const body = await readBody(request);
      const payload = JSON.parse(body.toString('utf8')) as { policyMode?: unknown };
      const policyMode = payload?.policyMode;
      if (policyMode !== 'auto' && policyMode !== 'review') {
        response.statusCode = 400;
        response.setHeader('Content-Type', 'application/json; charset=utf-8');
        response.end(JSON.stringify({ error: 'Invalid policyMode. Use auto or review.' }));
        return true;
      }

      const started = await startStudioNewReview({ policyMode });
      response.statusCode = 200;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify(started));
      return true;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      response.statusCode = 500;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: `Failed to start review: ${message}` }));
      return true;
    }
  }

  if (!(requestUrl.pathname === '/api' || requestUrl.pathname.startsWith('/api/'))) {
    return false;
  }

  const targetUrl = new URL(`${requestUrl.pathname}${requestUrl.search}`, workerUrl);
  const method = (request.method ?? 'GET').toUpperCase();
  const headers = createProxyHeaders(request.headers, {
    apiKey,
    reviewGithubToken,
    openrouterApiKey,
  });

  const body = method === 'GET' || method === 'HEAD' ? undefined : new Uint8Array(await readBody(request));
  const upstream = await fetch(targetUrl.toString(), {
    method,
    headers,
    body,
  });

  response.statusCode = upstream.status;
  response.statusMessage = upstream.statusText;
  upstream.headers.forEach((value, key) => {
    if (key.toLowerCase() === 'transfer-encoding') {
      return;
    }
    response.setHeader(key, value);
  });

  if (!upstream.body || method === 'HEAD') {
    response.end();
    return true;
  }

  const reader = upstream.body.getReader();
  while (true) {
    const { done, value } = await reader.read();
    if (done) {
      break;
    }
    if (!value || value.byteLength === 0) {
      continue;
    }
    if (!response.write(Buffer.from(value))) {
      await once(response, 'drain');
    }
  }
  response.end();
  return true;
}

import * as p from '@clack/prompts';
import { spawn } from 'child_process';
import {
  resolveMonorepoDistDir,
  resolveMonorepoReportUiDir,
  resolvePackagedDistDir,
} from './ui-static.js';
import { startDevServerSession } from './ui-dev-server.js';
import { startStaticServerSession } from './ui-static-server.js';

const LOCAL_HOST = '127.0.0.1';

export interface UiServerSession {
  appUrl: string;
  uiMode: 'static' | 'dev';
  close: () => Promise<void>;
  waitForExit: () => Promise<void>;
}

export function openBrowser(url: string): void {
  const platform = process.platform;
  const command = platform === 'win32' ? 'cmd' : platform === 'darwin' ? 'open' : 'xdg-open';
  const args = platform === 'win32' ? ['/c', 'start', '', url] : [url];
  const child = spawn(command, args, {
    detached: true,
    stdio: 'ignore',
  });
  child.unref();
}

export async function startReportUiSession(options: {
  routePath: string;
  port: number;
  workerUrl: string;
  apiKey: string | null;
  reviewGithubToken: string | null;
  openrouterApiKey: string | null;
  preferDevServer?: boolean;
  repoRoot?: string;
}): Promise<UiServerSession> {
  if (options.preferDevServer) {
    const reportUiDir = resolveMonorepoReportUiDir();
    if (!reportUiDir) {
      throw new Error('Unable to locate monorepo report-ui package for --dev-ui mode.');
    }
    return startDevServerSession({
      routePath: options.routePath,
      reportUiDir,
      repoRoot: options.repoRoot,
      workerUrl: options.workerUrl,
      port: options.port,
    });
  }

  const bundledDistDir = resolvePackagedDistDir();
  const monorepoDistDir = resolveMonorepoDistDir();
  const distDir = bundledDistDir ?? monorepoDistDir;

  if (distDir) {
    p.log.message(
      `Serving report UI assets from ${distDir} on ${LOCAL_HOST}:${options.port} with API proxy target ${options.workerUrl}`
    );
    return startStaticServerSession({
      routePath: options.routePath,
      distDir,
      workerUrl: options.workerUrl,
      apiKey: options.apiKey,
      reviewGithubToken: options.reviewGithubToken,
      openrouterApiKey: options.openrouterApiKey,
      port: options.port,
    });
  }

  const reportUiDir = resolveMonorepoReportUiDir();
  if (!reportUiDir) {
    throw new Error('Unable to locate bundled report UI assets or monorepo report-ui package. Reinstall or rebuild the CLI package.');
  }

  return startDevServerSession({
    routePath: options.routePath,
    reportUiDir,
    repoRoot: options.repoRoot,
    workerUrl: options.workerUrl,
    port: options.port,
  });
}

import { createServer, type Server } from 'http';
import { createReviewEventsFanout } from './ui-events-fanout.js';
import { handleStaticRequest } from './ui-static.js';
import type { UiServerSession } from './ui-server.js';

const LOCAL_HOST = '127.0.0.1';

async function startStaticServer(options: {
  distDir: string;
  workerUrl: string;
  apiKey: string | null;
  reviewGithubToken: string | null;
  openrouterApiKey: string | null;
  port: number;
}): Promise<Server> {
  const reviewEventsFanout = createReviewEventsFanout({
    workerUrl: options.workerUrl,
    apiKey: options.apiKey,
    reviewGithubToken: options.reviewGithubToken,
    openrouterApiKey: options.openrouterApiKey,
  });

  const server = createServer((request, response) => {
    void handleStaticRequest(request, response, {
      distDir: options.distDir,
      reviewEventsFanout,
      workerUrl: options.workerUrl,
      apiKey: options.apiKey,
      reviewGithubToken: options.reviewGithubToken,
      openrouterApiKey: options.openrouterApiKey,
    });
  });
  server.on('close', () => {
    void reviewEventsFanout.close();
  });

  await new Promise<void>((resolveListen, rejectListen) => {
    const onError = (error: Error) => rejectListen(error);
    server.once('error', onError);
    server.listen(options.port, LOCAL_HOST, () => {
      server.off('error', onError);
      resolveListen();
    });
  });

  return server;
}

export async function startStaticServerSession(options: {
  routePath: string;
  distDir: string;
  workerUrl: string;
  apiKey: string | null;
  reviewGithubToken: string | null;
  openrouterApiKey: string | null;
  port: number;
}): Promise<UiServerSession> {
  const appUrl = `http://${LOCAL_HOST}:${options.port}${options.routePath}`;
  const server = await startStaticServer({
    distDir: options.distDir,
    workerUrl: options.workerUrl,
    apiKey: options.apiKey,
    reviewGithubToken: options.reviewGithubToken,
    openrouterApiKey: options.openrouterApiKey,
    port: options.port,
  });

  return {
    appUrl,
    uiMode: 'static',
    close: async () => {
      if (!server.listening) {
        return;
      }
      await new Promise<void>((resolveClose, rejectClose) => {
        server.close((error) => {
          if (error) {
            rejectClose(error);
            return;
          }
          resolveClose();
        });
      });
    },
    waitForExit: async () => {
      await new Promise<void>((_resolve, rejectWait) => {
        if (!server.listening) {
          rejectWait(new Error('Report UI server stopped unexpectedly.'));
          return;
        }
        const onClose = () => {
          server.off('error', onError);
          rejectWait(new Error('Report UI server stopped unexpectedly.'));
        };
        const onError = (error: Error) => {
          server.off('close', onClose);
          rejectWait(error);
        };
        server.once('close', onClose);
        server.once('error', onError);
      });
    },
  };
}

import { createReadStream, statSync } from 'fs';
import type { IncomingMessage, ServerResponse } from 'http';
import { dirname, extname, join, resolve, sep } from 'path';
import { fileURLToPath } from 'url';
import type { ReviewEventsFanout } from './ui-events-fanout.js';
import { proxyApiRequest } from './ui-proxy.js';

const LOCAL_HOST = '127.0.0.1';
const MODULE_DIR = dirname(fileURLToPath(import.meta.url));

const CONTENT_TYPES: Record<string, string> = {
  '.css': 'text/css; charset=utf-8',
  '.html': 'text/html; charset=utf-8',
  '.ico': 'image/x-icon',
  '.jpeg': 'image/jpeg',
  '.jpg': 'image/jpeg',
  '.js': 'application/javascript; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
  '.png': 'image/png',
  '.svg': 'image/svg+xml; charset=utf-8',
  '.txt': 'text/plain; charset=utf-8',
};

function ensureFilePath(rootDir: string, requestPath: string): string | null {
  const normalizedRoot = resolve(rootDir);
  const candidate = resolve(normalizedRoot, `.${requestPath}`);
  if (candidate !== normalizedRoot && !candidate.startsWith(`${normalizedRoot}${sep}`)) {
    return null;
  }
  return candidate;
}

function fileExists(path: string): boolean {
  try {
    return statSync(path).isFile();
  } catch {
    return false;
  }
}

export function resolveStaticEntry(distDir: string, rawPathname: string): string | null {
  let pathname = rawPathname;
  try {
    pathname = decodeURIComponent(rawPathname);
  } catch {
    pathname = rawPathname;
  }

  const indexPath = join(distDir, 'index.html');
  if (pathname === '/' || pathname.startsWith('/reports/')) {
    return fileExists(indexPath) ? indexPath : null;
  }

  const directFile = ensureFilePath(distDir, pathname);
  if (directFile && fileExists(directFile)) {
    return directFile;
  }

  if (!extname(pathname) && fileExists(indexPath)) {
    return indexPath;
  }

  return null;
}

export function contentTypeFor(path: string): string {
  return CONTENT_TYPES[extname(path).toLowerCase()] ?? 'application/octet-stream';
}

export async function handleStaticRequest(
  request: IncomingMessage,
  response: ServerResponse,
  options: {
    distDir: string;
    reviewEventsFanout: ReviewEventsFanout;
    workerUrl: string;
    apiKey: string | null;
    reviewGithubToken: string | null;
    openrouterApiKey: string | null;
  }
): Promise<void> {
  try {
    const handledReviewEvents = await options.reviewEventsFanout.handle(request, response);
    if (handledReviewEvents) {
      return;
    }

    const proxied = await proxyApiRequest(
      request,
      response,
      options.workerUrl,
      options.apiKey,
      options.reviewGithubToken,
      options.openrouterApiKey
    );
    if (proxied) {
      return;
    }

    const requestUrl = new URL(request.url ?? '/', `http://${LOCAL_HOST}`);
    const staticPath = resolveStaticEntry(options.distDir, requestUrl.pathname);
    if (!staticPath) {
      response.statusCode = 404;
      response.setHeader('Content-Type', 'text/plain; charset=utf-8');
      response.end('Not found');
      return;
    }

    const stats = statSync(staticPath);
    response.statusCode = 200;
    response.setHeader('Content-Type', contentTypeFor(staticPath));
    response.setHeader('Content-Length', String(stats.size));
    if ((request.method ?? 'GET').toUpperCase() === 'HEAD') {
      response.end();
      return;
    }

    createReadStream(staticPath)
      .on('error', () => {
        if (!response.headersSent) {
          response.statusCode = 500;
          response.setHeader('Content-Type', 'text/plain; charset=utf-8');
        }
        response.end('Failed to read static file.');
      })
      .pipe(response);
  } catch (error) {
    response.statusCode = 502;
    response.setHeader('Content-Type', 'text/plain; charset=utf-8');
    response.end(error instanceof Error ? error.message : 'Proxy error');
  }
}

export function resolvePackagedDistDir(): string | null {
  const bundled = resolve(MODULE_DIR, '..', '..', '..', 'assets', 'report-ui');
  if (fileExists(join(bundled, 'index.html'))) {
    return bundled;
  }
  return null;
}

export function resolveMonorepoDistDir(): string | null {
  const candidates = [
    resolve(process.cwd(), 'packages', 'report-ui', 'dist'),
    resolve(MODULE_DIR, '..', '..', '..', '..', 'report-ui', 'dist'),
  ];
  for (const candidate of candidates) {
    if (fileExists(join(candidate, 'index.html'))) {
      return candidate;
    }
  }
  return null;
}

export function resolveMonorepoReportUiDir(): string | null {
  const candidates = [
    resolve(process.cwd(), 'packages', 'report-ui'),
    resolve(MODULE_DIR, '..', '..', '..', '..', 'report-ui'),
  ];
  for (const candidate of candidates) {
    if (fileExists(join(candidate, 'package.json'))) {
      return candidate;
    }
  }
  return null;
}

