        if (stopped.stale) {
          throw new Error(
            `Could not stop existing Studio runtime on port ${runtime.port}. Runtime state is stale; run \`nimbus review studio --stop\` and retry.`
          );
        }
        throw new Error(
          `Could not stop existing Studio runtime on port ${runtime.port}. Please retry or use a different --port.`
        );
      }
      p.log.message('Stopped existing Studio runtime to start foreground session.');
    } else if (status.stale) {
      const cleared = await clearStaleReviewStudioRuntimeMetadata(runtime);
      if (cleared) {
        p.log.warning('Cleared stale Studio runtime metadata before foreground start.');
      }
    }

    openBrowser(appUrl);
    p.log.success(`Opened ${appUrl}`);
    await runStudioServeProcess(runtime);
    return;
  }

  const studio = await ensureReviewStudioRuntime(runtime, { routePath });
  openBrowser(studio.appUrl);
  p.log.success(`Opened ${studio.appUrl}`);
  p.log.message(studio.reused ? 'Reused existing Studio runtime.' : 'Started Studio runtime.');
}

import * as p from '@clack/prompts';
import { execFileSync } from 'child_process';
import { spawn } from 'child_process';
import { mkdir, readFile, rm, writeFile } from 'fs/promises';
import { join } from 'path';
import { getWorkerUrl } from '../../clients/worker/shared.js';
import { GitRepo } from '../../lib/checkpoint/git.js';
import { startStudioPreflightBackgroundPolling, stopStudioPreflightBackgroundPolling } from './studio-preflight-cache.js';
import { startReportUiSession } from './ui-server.js';

export const DEFAULT_OPEN_PORT = 2000;
export const LOCAL_HOST = '127.0.0.1';
const STUDIO_SCHEMA_VERSION = 1;
const STUDIO_READY_TIMEOUT_MS = 20_000;

type ReviewUiReporter = {
  warning: (message: string) => void;
};

const defaultReporter: ReviewUiReporter = {
  warning: (message) => p.log.warning(message),
};

export interface ReviewUiRuntimeContext {
  port: number;
  workerUrl: string;
  apiKey: string | null;
  reviewGithubToken: string | null;
  openrouterApiKey: string | null;
  preferDevUi: boolean;
}

export interface StudioRuntimeMetadata {
  schemaVersion: 1;
  pid: number;
  port: number;
  workerUrl: string;
  repoRoot: string;
  startedAt: string;
  replayCursors: Record<string, number>;
  uiMode?: 'static' | 'dev';
}

export interface StudioPreferences {
  schemaVersion: 1;
  policyMode: 'auto' | 'review';
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolvePromise) => setTimeout(resolvePromise, ms));
}

function resolveRepoRoot(): string {
  return new GitRepo(process.cwd()).getRepoRoot();
}

function resolveStudioPaths(repoRoot: string): {
  rootDir: string;
  runtimeDir: string;
  runtimePath: string;
  preferencesPath: string;
} {
  const rootDir = join(repoRoot, '.nimbus');
  const runtimeDir = join(rootDir, 'studio');
  return {
    rootDir,
    runtimeDir,
    runtimePath: join(runtimeDir, 'runtime.json'),
    preferencesPath: join(rootDir, 'studio.json'),
  };
}

async function readJsonFile<T>(path: string): Promise<T | null> {
  try {
    const raw = await readFile(path, 'utf8');
    return JSON.parse(raw) as T;
  } catch {
    return null;
  }
}

async function writeJsonFile(path: string, value: unknown): Promise<void> {
  await writeFile(path, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
}

async function ensureStudioPreferenceFile(repoRoot: string): Promise<void> {
  const paths = resolveStudioPaths(repoRoot);
  await mkdir(paths.rootDir, { recursive: true });
  const existing = await readJsonFile<StudioPreferences>(paths.preferencesPath);
  if (existing?.schemaVersion === STUDIO_SCHEMA_VERSION && (existing.policyMode === 'auto' || existing.policyMode === 'review')) {
    return;
  }
  const initial: StudioPreferences = {
    schemaVersion: STUDIO_SCHEMA_VERSION,
    policyMode: 'auto',
  };
  await writeJsonFile(paths.preferencesPath, initial);
}

function isValidStudioPolicyMode(value: unknown): value is StudioPreferences['policyMode'] {
  return value === 'auto' || value === 'review';
}

async function readRuntimeMetadata(repoRoot: string): Promise<StudioRuntimeMetadata | null> {
  const paths = resolveStudioPaths(repoRoot);
  const parsed = await readJsonFile<StudioRuntimeMetadata>(paths.runtimePath);
  if (!parsed || parsed.schemaVersion !== STUDIO_SCHEMA_VERSION) {
    return null;
  }
  if (!Number.isInteger(parsed.port) || parsed.port <= 0 || parsed.port > 65535) {
    return null;
  }
  if (!Number.isInteger(parsed.pid) || parsed.pid <= 0) {
    return null;
  }
  return parsed;
}

async function writeRuntimeMetadata(repoRoot: string, metadata: StudioRuntimeMetadata): Promise<void> {
  const paths = resolveStudioPaths(repoRoot);
  await mkdir(paths.runtimeDir, { recursive: true });
  await writeJsonFile(paths.runtimePath, metadata);
}

async function clearRuntimeMetadataIfOwned(repoRoot: string, pid: number): Promise<void> {
  const paths = resolveStudioPaths(repoRoot);
  const current = await readRuntimeMetadata(repoRoot);
  if (current?.pid !== pid) {
    return;
  }
  await rm(paths.runtimePath, { force: true }).catch(() => undefined);
}

async function clearRuntimeMetadata(repoRoot: string): Promise<void> {
  const paths = resolveStudioPaths(repoRoot);
  await rm(paths.runtimePath, { force: true }).catch(() => undefined);
}

async function isStudioRuntimeHealthy(metadata: StudioRuntimeMetadata): Promise<boolean> {
  try {
    process.kill(metadata.pid, 0);
  } catch {
    return false;
  }
  try {
    const response = await fetch(`http://${LOCAL_HOST}:${metadata.port}/`, { method: 'GET' });
    return response.status < 500;
  } catch {
    return false;
  }
}

function resolveListeningPidByPort(port: number): number | null {
  try {
    const output = execFileSync('lsof', ['-nP', `-iTCP:${port}`, '-sTCP:LISTEN', '-t'], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    })
      .toString()
      .trim();
    if (!output) {
      return null;
    }
    const firstLine = output.split(/\r?\n/)[0]?.trim();
    const pid = Number.parseInt(firstLine ?? '', 10);
    return Number.isInteger(pid) && pid > 0 ? pid : null;
  } catch {
    return null;
  }
}

async function waitForProcessExit(pid: number, timeoutMs = 5_000): Promise<boolean> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      process.kill(pid, 0);
    } catch {
      return true;
    }
    await sleep(100);
  }
  return false;
}

function buildDetachedStudioSpawnArgs(port: number, preferDevUi: boolean): string[] {
  if (!process.argv[1]) {
    throw new Error('Unable to resolve current CLI entrypoint for detached Studio launch.');
  }
  const args = [...process.execArgv, process.argv[1], 'review', 'studio', '--serve', '--port', String(port)];
  if (preferDevUi) {
    args.push('--dev-ui');
  }
  return args;
}

function launchDetachedStudioProcess(repoRoot: string, port: number, preferDevUi: boolean): number {
  const child = spawn(process.execPath, buildDetachedStudioSpawnArgs(port, preferDevUi), {
    cwd: repoRoot,
    detached: true,
    stdio: 'ignore',
    env: process.env,
  });
  child.unref();
  if (!child.pid) {
    throw new Error('Detached Studio launch did not return a process id.');
  }
  return child.pid;
}

async function waitForStudioReadiness(port: number, timeoutMs = STUDIO_READY_TIMEOUT_MS): Promise<void> {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try {
      const response = await fetch(`http://${LOCAL_HOST}:${port}/`, { method: 'GET' });
      if (response.status < 500) {
        return;
      }
    } catch {
    }
    await sleep(250);
  }
  throw new Error(`Timed out waiting for Studio runtime on ${LOCAL_HOST}:${port}.`);
}

export function resolveReviewUiRuntimeContext(
  options?: {
    port?: number;
    preferDevUi?: boolean;
    reporter?: ReviewUiReporter;
  }
): ReviewUiRuntimeContext {
  const reporter = options?.reporter ?? defaultReporter;
  const port = options?.port ?? DEFAULT_OPEN_PORT;
  if (!Number.isInteger(port) || port <= 0 || port > 65535) {
    throw new Error('Invalid port. Use an integer between 1 and 65535.');
  }

  const workerUrl = getWorkerUrl();
  const apiKey = process.env.NIMBUS_API_KEY?.trim() ?? null;
  const reviewGithubToken = process.env.REVIEW_CONTEXT_GITHUB_TOKEN?.trim() ?? null;
  const openrouterApiKey = process.env.OPENROUTER_API_KEY?.trim() ?? null;
  if (!apiKey) {
    reporter.warning('NIMBUS_API_KEY is not set. Hosted worker requests may be rejected as unauthenticated.');
  }

  return {
    port,
    workerUrl,
    apiKey,
    reviewGithubToken,
    openrouterApiKey,
    preferDevUi: Boolean(options?.preferDevUi),
  };
}

export async function ensureReviewStudioRuntime(
  runtime: ReviewUiRuntimeContext,
  options?: { routePath?: string }
): Promise<{ appUrl: string; reused: boolean }> {
  const repoRoot = resolveRepoRoot();
  const routePath = options?.routePath ?? '/';
  await ensureStudioPreferenceFile(repoRoot);

  const existing = await readRuntimeMetadata(repoRoot);
  if (existing && existing.port === runtime.port && (await isStudioRuntimeHealthy(existing))) {
    const existingIsDev = existing.uiMode === 'dev';
    if (runtime.preferDevUi && !existingIsDev) {
      try {
        process.kill(existing.pid, 'SIGTERM');
        await waitForProcessExit(existing.pid);
      } catch {
      }
      await clearRuntimeMetadata(repoRoot);
    } else {
      return {
        appUrl: `http://${LOCAL_HOST}:${runtime.port}${routePath}`,
        reused: true,
      };
    }
  }

  }

  const pid = launchDetachedStudioProcess(repoRoot, runtime.port, runtime.preferDevUi);
  await writeRuntimeMetadata(repoRoot, {
    schemaVersion: STUDIO_SCHEMA_VERSION,
    pid,
    port: runtime.port,
    workerUrl: runtime.workerUrl,
    repoRoot,
    startedAt: new Date().toISOString(),
    replayCursors: {},
  });
  try {
    await waitForStudioReadiness(runtime.port);
  } catch (error) {
    await clearRuntimeMetadataIfOwned(repoRoot, pid);
    throw error;
  }
  return {
    appUrl: `http://${LOCAL_HOST}:${runtime.port}${routePath}`,
    reused: false,
  };
}

export async function runStudioServeProcess(runtime: ReviewUiRuntimeContext): Promise<void> {
  const repoRoot = resolveRepoRoot();
  await ensureStudioPreferenceFile(repoRoot);
  startStudioPreflightBackgroundPolling({ repoRoot });
  let uiSession: Awaited<ReturnType<typeof startReportUiSession>> | null = null;
  try {
    uiSession = await startReportUiSession({
      routePath: '/',
      port: runtime.port,
      workerUrl: runtime.workerUrl,
      apiKey: runtime.apiKey,
      reviewGithubToken: runtime.reviewGithubToken,
      openrouterApiKey: runtime.openrouterApiKey,
      preferDevServer: runtime.preferDevUi,
      repoRoot,
    });

    await writeRuntimeMetadata(repoRoot, {
      schemaVersion: STUDIO_SCHEMA_VERSION,
      pid: process.pid,
      port: runtime.port,
      workerUrl: runtime.workerUrl,
      repoRoot,
      startedAt: new Date().toISOString(),
      replayCursors: {},
      uiMode: uiSession.uiMode,
    });
  } catch (error) {
    stopStudioPreflightBackgroundPolling();
    if (uiSession) {
      await uiSession.close().catch(() => undefined);
    }
    throw error;
  }
  const activeSession = uiSession;
  if (!activeSession) {
    stopStudioPreflightBackgroundPolling();
    throw new Error('Studio UI session did not initialize.');
  }

  let shuttingDown = false;
  const shutdown = async () => {
    if (shuttingDown) {
      return;
    }
    shuttingDown = true;
    stopStudioPreflightBackgroundPolling();
    await activeSession.close().catch(() => undefined);
    await clearRuntimeMetadataIfOwned(repoRoot, process.pid);
  };
  const handleSignal = () => {
    void shutdown();
  };

  process.on('SIGINT', handleSignal);
  process.on('SIGTERM', handleSignal);
  try {
    await activeSession.waitForExit();
  } finally {
    process.off('SIGINT', handleSignal);
    process.off('SIGTERM', handleSignal);
    await shutdown();
  }
}

export async function getReviewStudioRuntimeStatus(
  runtime: ReviewUiRuntimeContext,
  options?: { repoRoot?: string }
): Promise<{
  running: boolean;
  stale: boolean;
  appUrl: string;
  runtime: StudioRuntimeMetadata | null;
}> {
  const repoRoot = options?.repoRoot ?? resolveRepoRoot();
  const runtimeMetadata = await readRuntimeMetadata(repoRoot);
  if (!runtimeMetadata) {
    const untrackedPid = resolveListeningPidByPort(runtime.port);
    if (untrackedPid) {
      return {
        running: true,
        stale: true,
        appUrl: `http://${LOCAL_HOST}:${runtime.port}/`,
        runtime: null,
      };
    }
    return {
      appUrl: `http://${LOCAL_HOST}:${runtime.port}/`,
      running: false,
      stale: false,
      runtime: null,
    };
  }
  const healthy = runtimeMetadata.port === runtime.port && (await isStudioRuntimeHealthy(runtimeMetadata));
  return {
    running: healthy,
    stale: !healthy,
    appUrl: `http://${LOCAL_HOST}:${runtime.port}/`,
    runtime: runtimeMetadata,
  };
}

export async function stopReviewStudioRuntime(
  runtime: ReviewUiRuntimeContext,
  options?: { repoRoot?: string }
): Promise<{ stopped: boolean; stale: boolean }> {
  const repoRoot = options?.repoRoot ?? resolveRepoRoot();
  const runtimeMetadata = await readRuntimeMetadata(repoRoot);
  if (!runtimeMetadata) {
    const untrackedPid = resolveListeningPidByPort(runtime.port);
    if (!untrackedPid) {
      return { stopped: false, stale: false };
    }
    try {
      process.kill(untrackedPid, 'SIGTERM');
      const stoppedByPort = await waitForProcessExit(untrackedPid);
      return { stopped: stoppedByPort, stale: !stoppedByPort };
    } catch {
      return { stopped: false, stale: true };
    }
  }

  if (runtimeMetadata.port !== runtime.port) {
    return { stopped: false, stale: false };
  }

  const metadataPid = runtimeMetadata.pid;
  let stale = false;
  let stopped = false;
  try {
    process.kill(metadataPid, 'SIGTERM');
    stopped = await waitForProcessExit(metadataPid);
  } catch {
    stale = true;
    stopped = false;
  } finally {
    await clearRuntimeMetadata(repoRoot);
  }
  if (stopped) {
    return { stopped: true, stale: false };
  }

  const fallbackPid = resolveListeningPidByPort(runtime.port);
  if (fallbackPid && fallbackPid !== metadataPid) {
    try {
      process.kill(fallbackPid, 'SIGTERM');
      const stoppedByPort = await waitForProcessExit(fallbackPid);
      return { stopped: stoppedByPort, stale: !stoppedByPort || stale };
    } catch {
      return { stopped: false, stale: true };
    }
  }
  return { stopped, stale };
}

export async function clearStaleReviewStudioRuntimeMetadata(
  runtime: ReviewUiRuntimeContext,
  options?: { repoRoot?: string }
): Promise<boolean> {
  const repoRoot = options?.repoRoot ?? resolveRepoRoot();
  const runtimeMetadata = await readRuntimeMetadata(repoRoot);
  if (!runtimeMetadata) {
    return false;
  }
  if (runtimeMetadata.port !== runtime.port) {
    return false;
  }
  if (await isStudioRuntimeHealthy(runtimeMetadata)) {
    return false;
  }
  await clearRuntimeMetadata(repoRoot);
  return true;
}

export async function readStudioPreferencesForTests(repoRoot: string): Promise<StudioPreferences | null> {
  return readJsonFile<StudioPreferences>(resolveStudioPaths(repoRoot).preferencesPath);
}

export async function readStudioPreferences(options?: { repoRoot?: string }): Promise<StudioPreferences> {
  const repoRoot = options?.repoRoot ?? resolveRepoRoot();
  await ensureStudioPreferenceFile(repoRoot);
  const existing = await readJsonFile<StudioPreferences>(resolveStudioPaths(repoRoot).preferencesPath);
  if (existing?.schemaVersion === STUDIO_SCHEMA_VERSION && isValidStudioPolicyMode(existing.policyMode)) {
    return existing;
  }
  const fallback: StudioPreferences = {
    schemaVersion: STUDIO_SCHEMA_VERSION,
    policyMode: 'auto',
  };
  await writeJsonFile(resolveStudioPaths(repoRoot).preferencesPath, fallback);
  return fallback;
}

export async function updateStudioPolicyMode(
  policyMode: StudioPreferences['policyMode'],
  options?: { repoRoot?: string }
): Promise<StudioPreferences> {
  if (!isValidStudioPolicyMode(policyMode)) {
    throw new Error('Invalid Studio policy mode. Use auto or review.');
  }
  const repoRoot = options?.repoRoot ?? resolveRepoRoot();
  await ensureStudioPreferenceFile(repoRoot);
  const next: StudioPreferences = {
    schemaVersion: STUDIO_SCHEMA_VERSION,
    policyMode,
  };
  await writeJsonFile(resolveStudioPaths(repoRoot).preferencesPath, next);
  return next;
}

export async function readStudioRuntimeForTests(repoRoot: string): Promise<StudioRuntimeMetadata | null> {
  return readRuntimeMetadata(repoRoot);
}

export async function ensureStudioPreferencesForTests(repoRoot: string): Promise<void> {
  await ensureStudioPreferenceFile(repoRoot);
}

import * as p from '@clack/prompts';
import { workspaceDeployCommand } from '../../commands/workspace/deploy.js';
import { createWorkspaceFromResolvedSource, resolveWorkspaceSource } from '../../commands/workspace/create.js';
import { resolveCochangeFromLocalGit } from '../../lib/entire/context.js';
import {
  setReviewPreflightCommitResolverForTests,
  type ReviewEntireContextResolution,
  validateReviewCochangeTokenReadiness,
  validateReviewCommitCheckpoint,
  validateReviewEntireIntentContext,
} from '../../commands/review/preflight.js';
import type { WorkspaceDeploymentResponse, WorkspaceResponse } from '../../lib/types.js';
import {
  COCHANGE_LOOKBACK_SESSIONS,
  COCHANGE_TOP_N,
  ReviewCreateProvenance,
  buildWorkspaceIdempotencyKey,
  deriveIdempotencyKey,
  isExpectedLocalCochangeResolutionError,
  normalizeCommitDiffPatch,
  parseChangedPathsFromDiff,
  resolveReviewGitProvenance,
} from './create-shared.js';

interface CommitResolution {
  commitSha: string;
  checkpointId: string | null;
  commitDiffPatch: string;
}

type SpinnerLike = {
  start: (message: string) => void;
  message: (message: string) => void;
  stop: (message?: string) => void;
};

export interface ResolveReviewContextOptions {
  commitish?: string;
  baseRef?: string;
  projectRoot?: string;
  idempotencyKey?: string;
  pollIntervalMs?: number;
  intentSummaryModel?: string;
}

export interface ResolveReviewContextResult {
  workspaceId: string;
  deploymentId: string;
  resolvedProvenance: ReviewCreateProvenance;
}

export interface ReviewContextFlowOverrides {
  createWorkspace?: typeof createWorkspaceForCommitFlow;
  resolveWorkspaceSource?: typeof resolveWorkspaceSourceForCommitFlow;
  deployWorkspace?: typeof deployWorkspaceForCommitFlow;
  resolveLocalCochange?: typeof resolveLocalCochangeForCommitFlow;
}

function toErrorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function buildReviewFlowStageError(stage: string, error: unknown): Error {
  return new Error(`Review flow failed at ${stage}: ${toErrorMessage(error)}`);
}

let createWorkspaceForCommitFlow: (source: {
  commitSha: string;
  checkpointId: string | null;
  sourceRef: string | null;
  projectRoot: string;
}) => Promise<{ workspace: WorkspaceResponse }> = createWorkspaceFromResolvedSource;
let resolveWorkspaceSourceForCommitFlow: typeof resolveWorkspaceSource = resolveWorkspaceSource;
let deployWorkspaceForCommitFlow: (
  workspaceId: string,
  options: Parameters<typeof workspaceDeployCommand>[1]
) => Promise<WorkspaceDeploymentResponse | null> = workspaceDeployCommand;
let resolveLocalCochangeForCommitFlow: typeof resolveCochangeFromLocalGit = resolveCochangeFromLocalGit;

export function setReviewCommitResolverForTests(
  resolver: ((commitish: string, options?: { baseRef?: string }) => CommitResolution) | null
): void {
  setReviewPreflightCommitResolverForTests(resolver);
}

export function setReviewContextFlowForTests(overrides: ReviewContextFlowOverrides | null): void {
  createWorkspaceForCommitFlow = overrides?.createWorkspace ?? createWorkspaceFromResolvedSource;
  resolveWorkspaceSourceForCommitFlow = overrides?.resolveWorkspaceSource ?? resolveWorkspaceSource;
  deployWorkspaceForCommitFlow = overrides?.deployWorkspace ?? workspaceDeployCommand;
  resolveLocalCochangeForCommitFlow = overrides?.resolveLocalCochange ?? resolveCochangeFromLocalGit;
}

/**
 * Orchestrates review context setup from a commit by validating Entire metadata,
 * creating a workspace, deploying it, then assembling provenance for review creation.
 */
export async function resolveReviewContext(
  options?: ResolveReviewContextOptions
): Promise<ResolveReviewContextResult> {
  const commitish = options?.commitish?.trim() || 'HEAD';
  const projectRoot = options?.projectRoot?.trim() || '.';
  const spinner: SpinnerLike =
    process.stdout.isTTY && process.stderr.isTTY
      ? p.spinner()
      : {
          start: () => undefined,
          message: () => undefined,
          stop: () => undefined,
        };

  let commitSha = '';
  let checkpointId = '';
  let commitDiffPatch = '';
  let workspaceId = '';
  let deploymentId = '';
  let commitDiffPatchSha256 = '';
  let commitDiffPatchTruncated = false;
  let commitDiffPatchOriginalChars = 0;
  let entireContextResolution: ReviewEntireContextResolution | null = null;
  let localCochange:
    | {
        source: 'local_git';
        checkpointsRef: string;
        lookbackSessions: number;
        topN: number;
        sessionsScanned: number;
        relatedByChangedPath: Record<string, Array<{ path: string; frequency: number; sessionIds: string[] }>>;
      }
    | null = null;
  let changedPaths: string[] = [];
  let gitProvenance: { repo: string; branch: string } = { repo: '', branch: '' };

  spinner.start('Resolving checkpoint...');
  try {
    gitProvenance = resolveReviewGitProvenance();
    const resolvedCommit = validateReviewCommitCheckpoint(commitish, process.cwd(), {
      baseRef: options?.baseRef,
    });
    commitSha = resolvedCommit.commitSha;
    checkpointId = resolvedCommit.checkpointId;
    changedPaths = parseChangedPathsFromDiff(resolvedCommit.commitDiffPatch);
    const normalizedPatch = normalizeCommitDiffPatch(resolvedCommit.commitDiffPatch);
    commitDiffPatch = normalizedPatch.patch;
    commitDiffPatchSha256 = normalizedPatch.sha256;
    commitDiffPatchTruncated = normalizedPatch.truncated;
    commitDiffPatchOriginalChars = normalizedPatch.originalChars;
    spinner.stop(`Resolved checkpoint ${checkpointId} from ${commitSha.slice(0, 12)}`);
  } catch (error) {
    spinner.stop('Checkpoint resolution failed');
    throw buildReviewFlowStageError('checkpoint resolution', error);
  }

  spinner.start('Validating Entire session metadata...');
  try {
    entireContextResolution = await validateReviewEntireIntentContext(
      {
        commitSha,
        checkpointId,
      },
      {
        summarizeSession: 'auto',
        allowBranchFallback: true,
      },
      process.cwd()
    );

    spinner.stop(
      entireContextResolution.contextResolution === 'branch_fallback'
        ? `Entire session metadata resolved via branch fallback (${entireContextResolution.resolvedCheckpointId})`
        : 'Entire session metadata is readable'
    );
    if (entireContextResolution.contextResolution === 'branch_fallback') {
      p.log.warning(
        `Using fallback Entire context from commit ${entireContextResolution.resolvedCommitSha.slice(0, 7)} ('${entireContextResolution.resolvedCommitSubject}') ${entireContextResolution.commitsAgo} commits ago.`
      );
    }
  } catch (error) {
    spinner.stop('Entire session metadata validation failed');
    throw buildReviewFlowStageError('checkpoint resolution', error);
  }

  spinner.start('Resolving local co-change context...');
  try {
    localCochange = resolveLocalCochangeForCommitFlow(changedPaths, process.cwd(), {
      lookbackSessions: COCHANGE_LOOKBACK_SESSIONS,
      topN: COCHANGE_TOP_N,
    });
    if (localCochange) {
      spinner.stop(
        `Resolved local co-change context from ${localCochange.checkpointsRef} (${localCochange.sessionsScanned} sessions scanned)`
      );
    } else {
      spinner.stop('Local co-change context unavailable (worker will use GitHub fallback)');
    }
  } catch (error) {
    localCochange = null;
    const message = toErrorMessage(error);
    if (!isExpectedLocalCochangeResolutionError(message)) {
      p.log.warning(`Local co-change resolution error: ${message}`);
    }
    spinner.stop('Local co-change context unavailable (worker will use GitHub fallback)');
  }

  spinner.start('Checking co-change token readiness...');
  try {
    if (localCochange) {
      spinner.stop('Co-change token check skipped (using local co-change context)');
    } else {
      await validateReviewCochangeTokenReadiness();
      spinner.stop('Co-change token readiness confirmed');
    }
  } catch (error) {
    spinner.stop('Co-change token readiness check failed');
    throw buildReviewFlowStageError('checkpoint resolution', error);
  }

  spinner.start('Creating workspace...');
  try {
    const sourceResolved = resolveWorkspaceSourceForCommitFlow(commitSha, { projectRoot });
    const source = {
      ...sourceResolved,
      checkpointId,
    };
    const created = await createWorkspaceForCommitFlow(source);
    workspaceId = created.workspace.id;
    spinner.stop(`Workspace created: ${workspaceId}`);
  } catch (error) {
    spinner.stop('Workspace creation failed');
    throw buildReviewFlowStageError('workspace creation', error);
  }

  spinner.start('Deploying workspace...');
  try {
    const deploymentIdempotencyKey = options?.idempotencyKey?.trim()
      ? deriveIdempotencyKey(options.idempotencyKey, 'deploy')
      : buildWorkspaceIdempotencyKey(commitSha);
    const deployment = await deployWorkspaceForCommitFlow(workspaceId, {
      idempotencyKey: deploymentIdempotencyKey,
      runTestsIfPresent: false,
      runBuildIfPresent: false,
      autoFix: false,
      pollIntervalMs: options?.pollIntervalMs,
      reporter: {
        message: (text) => spinner.message(text),
        success: (text) => spinner.message(text),
        warning: (text) => spinner.message(text),
        error: (text) => spinner.message(text),
      },
      entireIntentContextOverride: entireContextResolution ?? undefined,
    });
    if (!deployment) {
      throw new Error('Workspace deploy returned no deployment result.');
    }
    deploymentId = deployment.id;
    spinner.stop(`Deployment succeeded: ${deploymentId}`);
  } catch (error) {
    spinner.stop('Workspace deploy failed');
    throw buildReviewFlowStageError('workspace deploy', error);
  }

import { once } from 'events';
import type { IncomingMessage, ServerResponse } from 'http';
import { GitRepo } from '../../lib/checkpoint/git.js';
import { detectRepoSlugFromGitOrigin } from '../../lib/git.js';
import { startStudioNewReview } from './studio-create.js';
import { getStudioNewReviewPreflightCached } from './studio-preflight-cache.js';
import { createProxyHeaders } from './ui-events-fanout.js';

const LOCAL_HOST = '127.0.0.1';
const STUDIO_CONTEXT_PATH = '/api/studio/context';
const STUDIO_NEW_REVIEW_PREFLIGHT_PATH = '/api/studio/new-review/preflight';
const STUDIO_NEW_REVIEW_START_PATH = '/api/studio/new-review/start';

function resolveRepoRootSafe(): string | undefined {
  try {
    return new GitRepo(process.cwd()).getRepoRoot();
  } catch {
    return undefined;
  }
}

async function readBody(request: IncomingMessage): Promise<Buffer> {
  const chunks: Buffer[] = [];
  for await (const chunk of request) {
    if (typeof chunk === 'string') {
      chunks.push(Buffer.from(chunk));
    } else {
      chunks.push(chunk);
    }
  }
  return Buffer.concat(chunks);
}

export async function proxyApiRequest(
  request: IncomingMessage,
  response: ServerResponse,
  workerUrl: string,
  apiKey: string | null,
  reviewGithubToken: string | null,
  openrouterApiKey: string | null
): Promise<boolean> {
  const requestUrl = new URL(request.url ?? '/', `http://${LOCAL_HOST}`);
  if (requestUrl.pathname === STUDIO_CONTEXT_PATH) {
    const method = (request.method ?? 'GET').toUpperCase();
    if (method !== 'GET' && method !== 'HEAD') {
      response.statusCode = 405;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: 'Method not allowed' }));
      return true;
    }

    let repo: string | null = null;
    let branch: string | null = null;
    try {
      repo = detectRepoSlugFromGitOrigin();
    } catch {
      repo = null;
    }
    try {
      branch = new GitRepo(process.cwd()).getCurrentBranchRef();
    } catch {
      branch = null;
    }

    const payload = {
      repo,
      branch,
      detectedAt: new Date().toISOString(),
    };
    response.statusCode = 200;
    response.setHeader('Content-Type', 'application/json; charset=utf-8');
    if (method === 'HEAD') {
      response.end();
      return true;
    }
    response.end(JSON.stringify(payload));
    return true;
  }

  if (requestUrl.pathname === STUDIO_NEW_REVIEW_PREFLIGHT_PATH) {
    const method = (request.method ?? 'GET').toUpperCase();
    if (method !== 'GET' && method !== 'HEAD') {
      response.statusCode = 405;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: 'Method not allowed' }));
      return true;
    }
    try {
      const payload = await getStudioNewReviewPreflightCached({ repoRoot: resolveRepoRootSafe() });
      response.statusCode = 200;
      response.setHeader('Cache-Control', 'no-store');
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      if (method === 'HEAD') {
        response.end();
        return true;
      }
      response.end(JSON.stringify(payload));
      return true;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      response.statusCode = 500;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: `Failed to load Studio preflight: ${message}` }));
      return true;
    }
  }

  if (requestUrl.pathname === STUDIO_NEW_REVIEW_START_PATH) {
    const method = (request.method ?? 'POST').toUpperCase();
    if (method !== 'POST') {
      response.statusCode = 405;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: 'Method not allowed' }));
      return true;
    }
    try {
      const body = await readBody(request);
      const payload = JSON.parse(body.toString('utf8')) as { policyMode?: unknown };
      const policyMode = payload?.policyMode;
      if (policyMode !== 'auto' && policyMode !== 'review') {
        response.statusCode = 400;
        response.setHeader('Content-Type', 'application/json; charset=utf-8');
        response.end(JSON.stringify({ error: 'Invalid policyMode. Use auto or review.' }));
        return true;
      }

      const started = await startStudioNewReview({ policyMode, repoRoot: resolveRepoRootSafe() });
      response.statusCode = 200;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify(started));
      return true;
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      response.statusCode = 500;
      response.setHeader('Content-Type', 'application/json; charset=utf-8');
      response.end(JSON.stringify({ error: `Failed to start review: ${message}` }));
      return true;
    }
  }

  if (!(requestUrl.pathname === '/api' || requestUrl.pathname.startsWith('/api/'))) {
    return false;
  }

  const targetUrl = new URL(`${requestUrl.pathname}${requestUrl.search}`, workerUrl);
  const method = (request.method ?? 'GET').toUpperCase();
  const headers = createProxyHeaders(request.headers, {
    apiKey,
    reviewGithubToken,
    openrouterApiKey,
  });

  const body = method === 'GET' || method === 'HEAD' ? undefined : new Uint8Array(await readBody(request));
  const upstream = await fetch(targetUrl.toString(), {
    method,
    headers,
    body,
  });

  response.statusCode = upstream.status;
  response.statusMessage = upstream.statusText;
  upstream.headers.forEach((value, key) => {
    if (key.toLowerCase() === 'transfer-encoding') {
      return;
    }
    response.setHeader(key, value);
  });

  if (!upstream.body || method === 'HEAD') {
    response.end();
    return true;
  }

  const reader = upstream.body.getReader();
  while (true) {
    const { done, value } = await reader.read();
    if (done) {
      break;
    }
    if (!value || value.byteLength === 0) {
      continue;
    }
    if (!response.write(Buffer.from(value))) {
      await once(response, 'drain');
    }
  }
  response.end();
  return true;
}

