import { execFileSync } from 'child_process';
import { readFileSync, watch, type FSWatcher } from 'fs';
import { join } from 'path';
import { GitRepo } from '../../lib/checkpoint/git.js';
import { resolveStudioNewReviewPreflight, type StudioNewReviewPreflightResult } from './studio-create.js';

interface PreflightCacheState {
  headSha: string | null;
  policyMode: 'auto' | 'review' | null;
  refreshedAtMs: number | null;
  value: StudioNewReviewPreflightResult | null;
  inFlight: Promise<StudioNewReviewPreflightResult> | null;
}

const PREFLIGHT_CACHE_MAX_AGE_MS = 8_000;

let cache: PreflightCacheState = {
  headSha: null,
  policyMode: null,
  refreshedAtMs: null,
  value: null,
  inFlight: null,
};
let headWatcher: FSWatcher | null = null;
let refWatcher: FSWatcher | null = null;
let studioPreferencesWatcher: FSWatcher | null = null;
let refreshDebounceTimer: NodeJS.Timeout | null = null;

function resolveHeadSha(repoRoot: string): string | null {
  try {
    return new GitRepo(repoRoot).resolveCommitSha('HEAD');
  } catch {
    return null;
  }
}

function resolveStudioPolicyMode(repoRoot: string): 'auto' | 'review' | null {
  try {
    const raw = JSON.parse(readFileSync(join(repoRoot, '.nimbus', 'studio.json'), 'utf8')) as {
      policyMode?: unknown;
    };
    if (raw.policyMode === 'auto' || raw.policyMode === 'review') {
      return raw.policyMode;
    }
    return null;
  } catch {
    return null;
  }
}

async function refreshPreflight(repoRoot: string): Promise<StudioNewReviewPreflightResult> {
  if (cache.inFlight) {
    return cache.inFlight;
  }
  const pending = (async () => {
    const result = await resolveStudioNewReviewPreflight({ repoRoot });
    cache = {
      headSha: resolveHeadSha(repoRoot),
      policyMode: resolveStudioPolicyMode(repoRoot),
      refreshedAtMs: Date.now(),
      value: result,
      inFlight: null,
    };
    return result;
  })();
  cache = {
    ...cache,
    inFlight: pending,
  };
  try {
    return await pending;
  } finally {
    if (cache.inFlight === pending) {
      cache = {
        ...cache,
        inFlight: null,
      };
    }
  }
}

function resolveGitDir(repoRoot: string): string | null {
  try {
    const output = execFileSync('git', ['rev-parse', '--git-dir'], {
      cwd: repoRoot,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    })
      .toString()
      .trim();
    if (!output) {
      return null;
    }
    return output.startsWith('/') ? output : join(repoRoot, output);
  } catch {
    return null;
  }
}

function resolveHeadRef(gitDir: string): string | null {
  try {
    const output = readFileSync(join(gitDir, 'HEAD'), 'utf8').trim();
    if (!output.startsWith('ref:')) {
      return null;
    }
    const headRef = output.slice(4).trim();
    return headRef || null;
  } catch {
    return null;
  }
}

function queueRefresh(repoRoot: string): void {
  if (refreshDebounceTimer) {
    clearTimeout(refreshDebounceTimer);
  }
  refreshDebounceTimer = setTimeout(() => {
    refreshDebounceTimer = null;
    void refreshPreflight(repoRoot).catch(() => undefined);
  }, 250);
  if (typeof refreshDebounceTimer.unref === 'function') {
    refreshDebounceTimer.unref();
  }
}

function closeWatchers(): void {
  if (headWatcher) {
    headWatcher.close();
    headWatcher = null;
  }
  if (refWatcher) {
    refWatcher.close();
    refWatcher = null;
  }
  if (studioPreferencesWatcher) {
    studioPreferencesWatcher.close();
    studioPreferencesWatcher = null;
  }
}

function watchHeadRefPath(repoRoot: string, gitDir: string): void {
  if (refWatcher) {
    refWatcher.close();
    refWatcher = null;
  }
  const headRef = resolveHeadRef(gitDir);
  if (!headRef || !headRef.startsWith('refs/')) {
    return;
  }
  const headRefPath = join(gitDir, ...headRef.split('/'));
  try {
    refWatcher = watch(headRefPath, () => {
      queueRefresh(repoRoot);
    });
  } catch {
    refWatcher = null;
  }
}

export async function getStudioNewReviewPreflightCached(options?: {
  repoRoot?: string;
}): Promise<StudioNewReviewPreflightResult> {
  const repoRoot = options?.repoRoot ?? process.cwd();
  const headSha = resolveHeadSha(repoRoot);
  const policyMode = resolveStudioPolicyMode(repoRoot);
  const cacheIsFresh =
    typeof cache.refreshedAtMs === 'number' && Date.now() - cache.refreshedAtMs <= PREFLIGHT_CACHE_MAX_AGE_MS;
  if (
    cache.value &&
    cacheIsFresh &&
    cache.headSha &&
    headSha &&
    cache.headSha === headSha &&
    cache.policyMode === policyMode
  ) {
    return cache.value;
  }
  return refreshPreflight(repoRoot);
}

export function startStudioPreflightBackgroundPolling(options?: {
  repoRoot?: string;
}): void {
  if (headWatcher) {
    return;
  }
  const repoRoot = options?.repoRoot ?? process.cwd();
  const gitDir = resolveGitDir(repoRoot);

  void refreshPreflight(repoRoot).catch(() => undefined);
  if (!gitDir) {
    return;
  }

  const headPath = join(gitDir, 'HEAD');
  try {
    headWatcher = watch(headPath, () => {
      watchHeadRefPath(repoRoot, gitDir);
      queueRefresh(repoRoot);
    });
  } catch {
    headWatcher = null;
    return;
  }
  watchHeadRefPath(repoRoot, gitDir);
  const studioPreferencesPath = join(repoRoot, '.nimbus', 'studio.json');
  try {
    studioPreferencesWatcher = watch(studioPreferencesPath, () => {
      queueRefresh(repoRoot);
    });
  } catch {
    studioPreferencesWatcher = null;
  }
}

export function stopStudioPreflightBackgroundPolling(): void {
  closeWatchers();
  if (refreshDebounceTimer) {
    clearTimeout(refreshDebounceTimer);
    refreshDebounceTimer = null;
  }
}

import * as p from '@clack/prompts';
import {
  clearStaleReviewStudioRuntimeMetadata,
  ensureReviewStudioRuntime,
  getReviewStudioRuntimeStatus,
  resolveReviewUiRuntimeContext,
  runStudioServeProcess,
  stopReviewStudioRuntime,
} from './session.js';
import { openBrowser } from './ui-server.js';

export interface OpenReviewFromCommitOptions {
  port?: number;
  commitish?: string;
  baseRef?: string;
  projectRoot?: string;
  idempotencyKey?: string;
  pollIntervalMs?: number;
}

export interface StartReviewStudioOptions {
  port?: number;
  routePath?: string;
  serve?: boolean;
  status?: boolean;
  stop?: boolean;
  devUi?: boolean;
  detach?: boolean;
}

export async function openReviewFromCommitCommand(options?: OpenReviewFromCommitOptions): Promise<void> {
  p.log.warning('`nimbus review open` is a compatibility path. Use `nimbus review studio` + `nimbus review create`.');
  const reviewModule = await import('./create-from-commit.js');
  await reviewModule.createReviewFromCommitCommand({
    commitish: options?.commitish,
    baseRef: options?.baseRef,
    projectRoot: options?.projectRoot,
    idempotencyKey: options?.idempotencyKey,
    pollIntervalMs: options?.pollIntervalMs,
    policyMode: 'review',
    openStudio: true,
    openStudioPort: options?.port,
  });
}

export async function startReviewStudioCommand(options?: StartReviewStudioOptions): Promise<void> {
  if (options?.serve) {
    const runtime = resolveReviewUiRuntimeContext({ port: options.port, preferDevUi: options.devUi });
    await runStudioServeProcess(runtime);
    return;
  }

  const runtime = resolveReviewUiRuntimeContext({ port: options?.port, preferDevUi: options?.devUi });
  if (options?.status) {
    const studioStatus = await getReviewStudioRuntimeStatus(runtime);
    if (studioStatus.running) {
      p.log.success(`Studio runtime is running at ${studioStatus.appUrl}`);
      if (studioStatus.runtime) {
        p.log.message(`PID: ${studioStatus.runtime.pid}`);
        p.log.message(`Started: ${studioStatus.runtime.startedAt}`);
      }
      return;
    }
    if (studioStatus.stale) {
      p.log.warning('Studio runtime metadata exists but runtime is not healthy.');
      return;
    }
    p.log.warning('Studio runtime is not running.');
    return;
  }

  if (options?.stop) {
    const stopped = await stopReviewStudioRuntime(runtime);
    if (stopped.stopped) {
      p.log.success('Stopped Studio runtime.');
      return;
    }
    if (stopped.stale) {
      p.log.warning('Studio runtime was stale. Cleared runtime metadata.');
      return;
    }
    p.log.warning('No running Studio runtime found for this repository.');
    return;
  }

  const routePath = options?.routePath ?? '/';
  const detach = options?.detach ?? Boolean(options?.routePath);
  if (!detach) {
    const appUrl = `http://127.0.0.1:${runtime.port}${routePath}`;
    const status = await getReviewStudioRuntimeStatus(runtime);
    if (status.running) {
      if (!status.runtime) {
        throw new Error(
          `Port ${runtime.port} is already in use by a non-Nimbus process. Use --port <n> or stop that process.`
        );
      }
      const stopped = await stopReviewStudioRuntime(runtime);
      if (!stopped.stopped) {
        if (stopped.stale) {
          throw new Error(
            `Could not stop existing Studio runtime on port ${runtime.port}. Runtime state is stale; run \`nimbus review studio --stop\` and retry.`
          );
        }
        throw new Error(
          `Could not stop existing Studio runtime on port ${runtime.port}. Please retry or use a different --port.`
        );
      }
      p.log.message('Stopped existing Studio runtime to start foreground session.');
    } else if (status.stale) {
      const cleared = await clearStaleReviewStudioRuntimeMetadata(runtime);
      if (cleared) {
        p.log.warning('Cleared stale Studio runtime metadata before foreground start.');
      }
    }

    openBrowser(appUrl);
    p.log.success(`Opened ${appUrl}`);
    await runStudioServeProcess(runtime);
    return;
  }

  const studio = await ensureReviewStudioRuntime(runtime, { routePath });
  openBrowser(studio.appUrl);
  p.log.success(`Opened ${studio.appUrl}`);
  p.log.message(studio.reused ? 'Reused existing Studio runtime.' : 'Started Studio runtime.');
}

