}

function readOptionalString(value: unknown): string | null {
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

function collectTranscriptPartText(parts: unknown): string[] {
  if (!Array.isArray(parts)) {
    return [];
  }

  return parts
    .flatMap((part) => {
      if (!part || typeof part !== 'object' || Array.isArray(part)) {
        return [];
      }
      const text = readOptionalString((part as Record<string, unknown>).text);
      return text ? [text] : [];
    })
    .filter(Boolean);
}

export function extractEntireTranscriptText(transcriptText: string): EntireTranscriptExtraction | null {
  const trimmed = transcriptText.trim();
  if (!trimmed) {
    return null;
  }

  let payload: unknown;
  try {
    payload = JSON.parse(trimmed);
  } catch {
    return null;
  }

  if (!payload || typeof payload !== 'object' || Array.isArray(payload)) {
    return null;
  }

  const messages = Array.isArray((payload as Record<string, unknown>).messages)
    ? ((payload as Record<string, unknown>).messages as unknown[])
    : [];
  if (messages.length === 0) {
    return null;
  }

  const userPromptBlocks: string[] = [];
  for (const message of messages) {
    if (!message || typeof message !== 'object' || Array.isArray(message)) {
      continue;
    }

    const messageRecord = message as Record<string, unknown>;
    const info = messageRecord.info;
    const role =
      info && typeof info === 'object' && !Array.isArray(info)
        ? readOptionalString((info as Record<string, unknown>).role)
        : null;
    if (role !== 'user') {
      continue;
    }

    const promptBlock = collectTranscriptPartText(messageRecord.parts).join('\n').trim();
    if (promptBlock) {
      userPromptBlocks.push(promptBlock);
    }
  }

  if (userPromptBlocks.length === 0) {
    return null;
  }

  const rawPromptText = userPromptBlocks.join('\n\n---\n\n').trim();
  if (!rawPromptText) {
    return null;
  }

  return {
    contextText: rawPromptText,
    rawPromptText,
  };
}

function parseTouchedFilesFromSessionMetadata(value: unknown): string[] {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    return [];
  }

  const record = value as Record<string, unknown>;
  const candidates = [
    record.touchedFiles,
    record.touched_files,
    record.files_touched,
    record.changedFiles,
    record.changed_files,
    record.files,
  ];
  for (const candidate of candidates) {
    if (!Array.isArray(candidate)) {
      continue;
    }
    const parsed = candidate
      .flatMap((entry) => {
        if (typeof entry === 'string') {
          return [entry.trim()];
        }
        if (!entry || typeof entry !== 'object' || Array.isArray(entry)) {
          return [];
        }
        const item = entry as Record<string, unknown>;
        const path = readOptionalString(item.path);
        return path ? [path] : [];
      })
      .filter(Boolean);
    if (parsed.length > 0) {
      return parsed;
    }
  }

  return [];
}

function parseChangedPathsFromDiff(patch: string): string[] {
  const paths = new Set<string>();
  for (const line of patch.split('\n')) {
    if (!line.startsWith('+++ ')) {
      continue;
    }
    const raw = line.slice(4).trim();
    if (!raw || raw === '/dev/null') {
      continue;
    }
    const normalized = raw.replace(/^b\//, '').replace(/^\.\//, '').trim();
    if (!normalized || normalized === '/dev/null') {
      continue;
    }
    paths.add(normalized);
  }
  return Array.from(paths);
}

function basename(path: string): string {
  const normalized = path.replace(/\\/g, '/').replace(/\/+/g, '/');
  const segments = normalized.split('/').filter(Boolean);
  return segments[segments.length - 1] ?? normalized;
}

function scoreIntentLineAgainstChangedPaths(line: string, changedPaths: string[]): number {
  const normalizedLine = line.toLowerCase();
  let score = 0;

  for (const changedPath of changedPaths) {
    const normalizedPath = changedPath.toLowerCase();
    if (normalizedLine.includes(normalizedPath)) {
      score += 8;
      continue;
    }
    const fileName = basename(normalizedPath);
    if (fileName && fileName.length > 3 && normalizedLine.includes(fileName)) {
      score += 3;
    }
  }

  if (/^(prohibition|constraint|goal signal)\s*:/i.test(line)) {
    score += 2;
  }
  if (/\b(do not|don't|must not|never|avoid|prefer|require|should)\b/i.test(line)) {
    score += 1;
  }
  if (/\b(run\s+git\s+diff|usage:|step\s+\d+|command:)\b/i.test(line)) {
    score -= 3;
  }

  return score;
}

